// Layered guardrail pipeline: each layer independent, all logged (plain JS)
function guardPipeline(text, ctx) {
  const log = [];
  if (text.length > ctx.maxLen) { log.push("oversize"); return { pass: false, layer: "input", log }; }
  if (/ignore|system:|disregard/i.test(text)) { log.push("injection-pattern"); return { pass: false, layer: "input", log }; }
  const redacted = text.replace(/\b[\w.]+@[\w.]+\.\w+\b/g, "[EMAIL]").replace(/\b\d{13,16}\b/g, "[CARD]");
  if (redacted !== text) log.push("pii-redacted");
  if (!ctx.quota.consume(ctx.user)) { log.push("rate-limited"); return { pass: false, layer: "rate", log }; }
  return { pass: true, text: redacted, log };
}
// Order: cheap structural checks first, PII before model/logs, quota always.

