function guardPipeline(text, maxLen) {
  if (text.length > maxLen) return { pass: false, layer: 'input' };
  if (/ignore|system:|disregard/i.test(text)) return { pass: false, layer: 'input' };
  const redacted = text.replace(/\b[\w.]+@[\w.]+\.\w+\b/g, '[EMAIL]').replace(/\b\d{13,16}\b/g, '[CARD]');
  return { pass: true, text: redacted };
}
